def tile_repeat(x, h, w, channels, repeat_h, repeat_w):
    # x: [h, w, channels]
    x = x.unsqueeze(2).unsqueeze(3)  # [h, w, 1, 1, channels]
    x = x.expand(h, w, repeat_h, repeat_w, channels)
    return x.reshape(h * repeat_h, w * repeat_w, channels)

def fn(x, **params):
